            <div class="permissions"><?php $__currentLoopData = $permissions; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $group=>$groupPermissions): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><fieldset><legend><?php echo e($group); ?></legend><?php $__currentLoopData = $groupPermissions; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $permission): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><label><input type="checkbox" name="permission_ids[]" value="<?php echo e($permission->id); ?>" <?php if(in_array((string)$permission->id,array_map('strval',old('permission_ids',[])),true)): echo 'checked'; endif; ?>><span><strong><?php echo e($permission->name); ?></strong><small><?php echo e($permission->slug); ?></small></span></label><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></fieldset><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></div>
