        <div class="role-list"><?php $__currentLoopData = $roles; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $role): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><article class="role-card"><div class="role-card-header"><div><h3><?php echo e($role->name); ?> <?php if($role->is_system): ?><span>System</span><?php endif; ?></h3><p><?php echo e($role->description ?: 'No description'); ?></p></div><strong><?php echo e(number_format($role->users_count)); ?> users</strong></div>
