            <details><summary><i class="fa-regular fa-pen-to-square"></i> Edit role</summary><form method="POST" action="<?php echo e(route('admin.admin-roles.update',$role)); ?>" class="role-form compact"><?php echo csrf_field(); ?> <?php echo method_field('PUT'); ?><div class="role-basics"><div class="field"><label>Name</label><input name="name" value="<?php echo e($role->name); ?>" required maxlength="100"></div><div class="field"><label>Description</label><input name="description" value="<?php echo e($role->description); ?>" maxlength="2000"></div></div><?php $rolePermissionIds=$role->permissions->pluck('id')->map(fn($id)=>(string)$id)->all(); ?><div class="permissions"><?php $__currentLoopData = $permissions; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $group=>$groupPermissions): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><fieldset><legend><?php echo e($group); ?></legend><?php $__currentLoopData = $groupPermissions; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $permission): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><label><input type="checkbox" name="permission_ids[]" value="<?php echo e($permission->id); ?>" <?php if(in_array((string)$permission->id,$rolePermissionIds,true)): echo 'checked'; endif; ?>><span><strong><?php echo e($permission->name); ?></strong><small><?php echo e($permission->slug); ?></small></span></label><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></fieldset><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></div><footer><button type="submit"><i class="fa-solid fa-floppy-disk"></i> Save Role</button></footer></form></details>
